parameters.jsCode:
const platformName = 'indeed_' + $('When Executed by Another Workflow').item.json.countryCode.toLowerCase().replace(/ /g, '_');

for (const item of $input.all()) {
  item.json.source = platformName;
}

return $input.all();

parameters.query:
UPDATE public.workflow_health 
SET loop_count = loop_count + 1 
WHERE workflow_tag = '{{ $json.source }}';

